$('structuresTab').onclick=()=>{$('structuresTab').classList.add('active');$('dosesTab').classList.remove('active');structurePanel.classList.remove('hidden');dosePanel.classList.add('hidden');};
$('dosesTab').onclick=()=>{$('dosesTab').classList.add('active');$('structuresTab').classList.remove('active');dosePanel.classList.remove('hidden');structurePanel.classList.add('hidden');};
$('rtToggle').classList.add('active');$('rtToggle').onclick=()=>{leftPanel.classList.toggle('hidden');$('rtToggle').classList.toggle('active',!leftPanel.classList.contains('hidden'));surfaceView?.resize();scheduleRender();};
$('imageModes').onclick=e=>{const mode=e.target.closest('[data-mode]')?.dataset.mode;if(!mode)return;if(mode==='quad'||mode==='3d')setView(mode);else{$('plane').value=mode;$('plane').onchange();}};
$('fieldsToggle').onchange=()=>{surfaceState.fields=$('fieldsToggle').checked;surfaceControls();surfaceAppearance();scheduleRender();};
const fusionHome=$('fusionControls').parentElement;$('modal').addEventListener('close',()=>{const controls=$('fusionControls');if(controls&&$('modal').contains(controls))fusionHome.append(controls);});$('fusionButton').onclick=()=>{modal('Image fusion',root=>root.append($('fusionControls')));};
$('searchImagesButton').onclick=$('discoverButton').onclick;
const originalLayoutView=setView;
setView=function(next){const bar=$('surfacebar');if(bar?.parentElement?.classList.contains('tile'))$('stage').before(bar);originalLayoutView(next);const tile=tiles().find(t=>t.dataset.kind==='3D');if(tile&&bar)tile.append(bar);document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===(next==='image'?$('plane').value:next)));document.querySelectorAll('#views [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(next==='quad'?'image':next)));};
const layoutModel=applyModel;
applyModel=function(m,initial=false){layoutModel(m,initial);$('version').textContent='· v0.2.47 · macOS build 7';$('registrationStatus').textContent=!m.hasImage?'RT-only · no CT/MR loaded':'RT in the same coordinate system';$('planstats').textContent=m.rois.length+' structures · '+m.doses.length+' doses · '+m.plans.length+' plans';$('patientIdentity').textContent=(m.title||'')+(m.patientId?' · ID: '+m.patientId:'');$('fieldsToggle').checked=surfaceState.fields;};
savePng=async function(canvas=null,name=view){const rect=canvas?.closest('.tile')?.getBoundingClientRect();try{const result=await rpc('save',{kind:'png',filename:filename(name),caption:caption(),...(rect?{rect:[rect.x,rect.y,rect.width,rect.height]}:{})});if(result.saved)status('PNG saved');}catch(e){error(e);}};
let tagsOpen=false,tagRequest=0;
$('tagsToggle').onclick=()=>{tagsOpen=!tagsOpen;$('tagsPanel').classList.toggle('hidden',!tagsOpen);$('tagsToggle').classList.toggle('active',tagsOpen);if(tagsOpen)showTags();surfaceView?.resize();scheduleRender();};
showTags=async function(){const revision=++tagRequest,root=$('tagsPanel');root.replaceChildren();const box=text('div','','tags'),search=document.createElement('input');search.type='search';search.placeholder='Search tag, name, VR, sequence path or value';search.id='tagSearch';const scroll=text('div','','tagscroll'),table=document.createElement('table');scroll.append(table);const source=picker('DICOM-Quelle',[[-1,'Aktuelles Bild'],...(model.tagSources||[]).map(s=>[s.id,s.label])],tagSourceId,id=>{tagSourceId=+id;showTags();});source.id='tagSourcePicker';box.append(source,search,scroll);root.append(box);try{const rows=await rpc('tags',{sourceId:tagSourceId,index:view==='image'&&$('plane').value==='Native'?+$('slice').value:model.nativeIndex});if(revision!==tagRequest)return;const nodes=[],stack=[];for(const row of rows){while(stack.length&&!row.Path.startsWith(stack.at(-1).row.Path+'/')&&!row.Path.startsWith(stack.at(-1).row.Path+'['))stack.pop();const node={row,parent:stack.at(-1)||null,children:[],depth:stack.length};node.parent?.children.push(node);nodes.push(node);if(row.VR==='SQ'||row.Name.trim().startsWith('Item ['))stack.push(node);}let selected=null,expanded=new Set(),searching=false;const ancestors=node=>{const a=[];for(let p=node.parent;p;p=p.parent)a.push(p);return a;};
 const paint=()=>{const query=search.value.trim().toLowerCase(),matching=new Set(),automatic=new Set();if(query){for(const n of nodes)if(Object.values(n.row).join(' ').toLowerCase().includes(query)){matching.add(n);ancestors(n).forEach(p=>{matching.add(p);automatic.add(p);});}}else if(searching&&selected)ancestors(selected).forEach(p=>expanded.add(p));searching=!!query;table.replaceChildren();for(const n of nodes){if(query?!matching.has(n):ancestors(n).some(p=>!expanded.has(p)))continue;const tr=document.createElement('tr');tr.classList.toggle('selected',n===selected);tr.dataset.path=n.row.Path;const tag=text('td',n.row.Tag+' '+n.row.VR),label=text('td','','taglabel'),value=text('td',n.row.Value);label.style.paddingLeft=(n.depth*12+5)+'px';if(n.children.length){const open=query?automatic.has(n):expanded.has(n);label.append(button(open?'▾':'▸',()=>{expanded.has(n)?expanded.delete(n):expanded.add(n);paint();}));label.firstChild.className='tagarrow';}label.append(document.createTextNode(n.row.Name.trim()));tr.append(tag,label,value);tr.onclick=()=>{selected=n;table.querySelectorAll('.selected').forEach(r=>r.classList.remove('selected'));tr.classList.add('selected');};tr.ondblclick=()=>modal('DICOM element',content=>{for(const [caption,value] of [['Tag',n.row.Tag],['Label',n.row.Name.trim()],['Value',n.row.Value]]){content.append(text('h3',caption));const area=document.createElement('textarea');area.readOnly=true;area.value=value;content.append(area,button('Copy',()=>native('copy',{text:value})));}});table.append(tr);}if(!query&&selected)for(const row of table.rows)if(row.dataset.path===selected.row.Path){row.scrollIntoView({block:'nearest'});break;}};search.oninput=paint;paint();}catch(e){error(e);}};
const oldShowDvhLayout=showDvh;
showDvh=function(){oldShowDvhLayout();const panel=$('stage').querySelector('.dvhpanel'),body=text('div','','dvhbody'),chart=panel.querySelector('.chart'),metrics=panel.querySelector('.metrics');body.append(chart,metrics);panel.append(body);};
const compactDvh=drawDvh;
drawDvh=function(){compactDvh();const root=$('metrics');if(!root||view!=='dvh')return;root.replaceChildren();for(const roi of model.rois){if(xHidden(roi))continue;const r=dvhs.get(roi.id),row=text('div','','dvhlegend');row.style.color=roi.color;const input=document.createElement('input');input.type='checkbox';input.checked=!hidden.has(roi.id);input.onchange=()=>{input.checked?hidden.delete(roi.id):hidden.add(roi.id);roiList();drawDvh();};const label=button(window.roiLabel(roi),()=>{window.dvhFocus=window.dvhFocus===roi.id?null:roi.id;drawDvh();});label.className='roiname';if(window.dvhFocus===roi.id)label.style.fontWeight='700';label.append(text('small',r?number(r.volume,2)+' cm³':'Not calculated'));row.title=r?'Dmean '+number(r.mean,2)+'\nDmedian '+number(r.median,2)+'\nDmax '+number(r.max,2)+'\nDmin '+number(r.min,2)+'\nD98 '+number(r.d98,2)+'\nD2 '+number(r.d2,2)+' '+r.units+'\nCoverage '+number(r.coverage*100,1)+'%\n'+r.status+' · '+r.message:'';row.append(input,label);root.append(row);}};
const extraPresets=[['auto','Auto'],['liver','Liver'],['custom','Custom']];for(const [id,label] of extraPresets)$('preset').add(new Option(label,id));
const oldPreset=$('preset').onchange;$('preset').onchange=async()=>{if($('preset').value==='auto'){try{const h=await rpc('histogram');if(h.available){$('width').value=Math.max(1,h.max-h.min);$('level').value=(h.min+h.max)/2;scheduleRender();}}catch(e){error(e);}}else if($('preset').value==='liver'){$('width').value=150;$('level').value=60;scheduleRender();}else if($('preset').value==='custom')showHistogram();else oldPreset();};
async function showHistogram(){try{const hist=await rpc('histogram');if(!hist.available)return;modal('Custom window',root=>{const canvas=document.createElement('canvas');canvas.width=520;canvas.height=180;canvas.style.width='100%';root.append(canvas);const ctx=canvas.getContext('2d'),paint=()=>{ctx.fillStyle='#111314';ctx.fillRect(0,0,520,180);const high=Math.max(1,...hist.bins);ctx.fillStyle='#64b5f6';hist.bins.forEach((n,i)=>ctx.fillRect(i*520/256,170-n/high*145,520/256,n/high*145));const width=+$('width').value,level=+$('level').value;ctx.strokeStyle='#ffd752';for(const bound of [level-width/2,level+width/2]){const x=(bound-hist.min)/(hist.max-hist.min)*520;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,180);ctx.stroke();}};let drag=null;canvas.onpointerdown=e=>{const x=(e.clientX-canvas.getBoundingClientRect().left)/canvas.clientWidth*(hist.max-hist.min)+hist.min,l=+$('level').value,w=+$('width').value;drag=Math.abs(x-(l-w/2))<Math.abs(x-(l+w/2))?'low':'high';canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;const value=hist.min+Math.max(0,Math.min(1,(e.clientX-canvas.getBoundingClientRect().left)/canvas.clientWidth))*(hist.max-hist.min),l=+$('level').value,w=+$('width').value,low=drag==='low'?Math.min(value,l+w/2-1):l-w/2,high=drag==='high'?Math.max(value,l-w/2+1):l+w/2;$('width').value=high-low;$('level').value=(high+low)/2;paint();scheduleRender();};canvas.onpointerup=()=>drag=null;paint();root.append(text('p','Drag the gold lower and upper window limits.'));});}catch(e){error(e);}}
const imageWithWindow=drawImage;
drawImage=function(canvas,f){imageWithWindow(canvas,f);const tile=canvas.closest('.tile');if(tile&&!tile.querySelector('.window-picker')){const select=document.createElement('select');select.className='window-picker';for(const option of $('preset').options)select.add(new Option(option.text,option.value));select.value=$('preset').value;select.onchange=()=>{$('preset').value=select.value;$('preset').onchange();};tile.append(select);}if(surfaceView&&tile&&['Axial','Coronal','Sagittal'].includes(tile.dataset.kind))surfaceView.setSlice?.(tile.dataset.kind,f,canvas);drawFields(canvas,f);};
function drawFields(canvas,f){if(!f.fields)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,point=p=>[p[0]*w,p[1]*h];ctx.save();for(const field of [...f.fields.fields].sort((a,b)=>Number(a.active)-Number(b.active))){ctx.strokeStyle=field.active?'#ffd752':'#aab1bb88';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=field.active?1.5:.65;ctx.beginPath();for(const loop of field.opening){loop.forEach((p,i)=>i?ctx.lineTo(...point(p)):ctx.moveTo(...point(p)));ctx.closePath();}ctx.stroke();if(field.track.length){ctx.beginPath();field.track.forEach((s,i)=>i&&!s.split?ctx.lineTo(...point(s.point)):ctx.moveTo(...point(s.point)));ctx.stroke();for(const s of field.track)if(s.tick){ctx.beginPath();ctx.moveTo(...point(s.point));ctx.lineTo(...point(s.outer));ctx.stroke();}}if(!field.arc||field.active){const a=point(field.source),b=point(field.iso);ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();ctx.setLineDash([]);const dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1,x=a[0]+dx*.25,y=a[1]+dy*.25;ctx.beginPath();ctx.moveTo(x-dx/len*7-dy/len*3,y-dy/len*7+dx/len*3);ctx.lineTo(x,y);ctx.lineTo(x-dx/len*7+dy/len*3,y-dy/len*7-dx/len*3);ctx.stroke();ctx.font='9px -apple-system';ctx.fillText('B'+field.number,a[0]+5,a[1]-8);}}ctx.restore();}
const loadingWithoutFolderAction=window.loading;window.loading=function(folder){loadingWithoutFolderAction(folder);if(!folder){const choose=button('Gesamten Plan laden …',()=>native('openContainingFolder'));choose.title='Lokalen DICOM-Ordner auswählen. Es wird nichts übertragen.';$('notice').append(choose);}};
window.webkit.messageHandlers.native.postMessage({op:'ready'});
